'use strict';
const $=s=>document.querySelector(s),money=n=>'$'+Number(n).toLocaleString('es-CL'),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},save=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let config=window.FINANCED_CONFIG,session=read('financed-auth',null),connected=false,busy=false,lastSync=0,view='overview',documentUrls=[];
const demo=()=>({account:{id:'preview',name:'Tú',username:'tu_usuario',balance:0},contacts:[],transactions:[],destinations:[]});
let state=demo();
function me(){return state.account}function player(id){return id===me()?.id?me():state.contacts.find(c=>c.id===id)}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function clearDocuments(){$('#modal-body').querySelectorAll('.document-preview').forEach(i=>{i.onload=null;i.onerror=null});documentUrls.forEach(u=>URL.revokeObjectURL(u));documentUrls=[];const body=$('#modal-body');body.querySelectorAll('input[type=file]').forEach(i=>i.value='');body.querySelectorAll('.document-preview').forEach(i=>i.removeAttribute('src'))}
function modal(title,html){clearDocuments();$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){clearDocuments();$('#modal').close()}
$('#close-modal').onclick=close;$('#modal').addEventListener('close',clearDocuments);$('#modal').addEventListener('cancel',clearDocuments);
async function request(path,body,auth=true){if(!config)throw Error('La conexión de Financed no está disponible');const headers={apikey:config.key,'Content-Type':'application/json'};if(auth){await ensureAuth();headers.Authorization='Bearer '+session.access_token}const r=await fetch(config.url+path,{method:'POST',headers,body:JSON.stringify(body)}),raw=await r.text(),d=raw?JSON.parse(raw):{};if(!r.ok){if(d.code==='PGRST202')throw Error('Falta ejecutar la actualización de Financed en Supabase.');throw Error(d.message||d.msg||d.error_description||d.error||'No se pudo completar la operación')}return d}
async function ensureAuth(){if(!session?.refresh_token)throw Error('Inicia sesión en tu cuenta Financed');if(session.expires_at>Date.now()/1000+60)return;storeSession(await request('/auth/v1/token?grant_type=refresh_token',{refresh_token:session.refresh_token},false))}
async function rpc(name,p={}){return request('/rest/v1/rpc/fn_'+name,p)}
async function sync(){state=await rpc('state');if(!state.account)throw Error('Completa tu nombre de usuario');connected=true;lastSync=Date.now();render()}
async function run(fn){if(busy)return;busy=true;document.querySelectorAll('button[type=submit],#confirm-operation,#complete-verification').forEach(b=>b.disabled=true);try{await fn()}catch(e){toast(e.message);const er=$('#modal-error');if(er)er.textContent=e.message}finally{busy=false;document.querySelectorAll('button[type=submit],#confirm-operation,#complete-verification').forEach(b=>b.disabled=false)}}
function navigate(v){view=v;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==v);document.querySelectorAll('.nav[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===v));const label={overview:'Mi cuenta',history:'Movimientos',players:'Contactos',bank:'Mi banco'};$('#page-label').textContent=label[v];$('#headline').innerHTML=v==='overview'?'Tu dinero,<br>con todo bajo control.':label[v];render()}
document.querySelectorAll('[data-view]').forEach(el=>el.onclick=()=>navigate(el.dataset.view));
function rows(list){return list.length?list.map(t=>{const incoming=t.to_id===me().id;return `<div class="transaction"><span class="transaction-icon ${incoming?'incoming':''}">${incoming?'↓':'↑'}</span><div><div class="transaction-title">${esc(t.concept)}</div><div class="transaction-meta">${esc(t.from_name)} → ${esc(t.to_name)} · ${new Date(t.created_at).toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}</div></div><div class="transaction-amount ${incoming?'positive':''}">${incoming?'+':'−'}${money(t.amount)}</div></div>`}).join(''):'<div class="empty">Todavía no hay movimientos.<br>Tu primer movimiento aparecerá aquí.</div>'}
function contactsHtml(){return state.contacts.length?state.contacts.map(c=>`<div class="player-row"><span class="avatar">${esc(c.name[0].toUpperCase())}</span><div><div class="name">${esc(c.name)}</div><div class="role">@${esc(c.username)}</div></div><button class="text-button contact-transfer" data-recipient="${esc(c.id)}">Transferir</button></div>`).join(''):'<div class="empty">Aún no tienes contactos.<br>Busca a alguien por su nombre de usuario.</div>'}
function render(){if(!me())return;$('#balance').innerHTML=money(me().balance)+'<span>,00</span>';$('#card-name').textContent=me().name;$('#profile-name').textContent=me().name;$('#profile-initial').textContent=me().name[0].toUpperCase();$('#card-code').textContent=me().id==='preview'?'FN 0012 0480':'FN '+me().id.replace(/-/g,'').slice(-8).toUpperCase();$('#side-username').textContent='@'+me().username;$('#player-count').textContent=state.contacts.length+' contactos';const selected=$('#recipient').value;$('#recipient').innerHTML='<option value="">Seleccionar contacto</option>'+state.contacts.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · @${esc(c.username)}</option>`).join('');if(state.contacts.some(c=>c.id===selected))$('#recipient').value=selected;$('#recent-list').innerHTML=rows(state.transactions.slice(0,4));$('#history-list').innerHTML=rows(state.transactions);$('#players-mini').innerHTML=contactsHtml();$('#players-list').innerHTML=contactsHtml();document.querySelectorAll('[data-recipient]').forEach(b=>b.onclick=()=>{navigate('overview');$('#recipient').value=b.dataset.recipient;$('#amount').focus()});$('#connection-banner').innerHTML=connected?`<span>Cuenta sincronizada</span> Actualizada ${new Date(lastSync).toLocaleTimeString('es-CL',{hour:'2-digit',minute:'2-digit'})}<button id="sync-now">Actualizar</button>`:'<span>Vista previa</span> Explora tu cuenta Financed.<button id="activate-account">Activar cuenta</button>';if($('#sync-now'))$('#sync-now').onclick=()=>run(sync);if($('#activate-account'))$('#activate-account').onclick=()=>showAuth('signup');renderDestinations()}
function renderDestinations(){const current=$('#bank-destination').value;$('#bank-destination').innerHTML='<option value="">Elige tu cuenta de destino</option>'+state.destinations.map(d=>`<option value="${esc(d.id)}">${esc(d.bank)} · ${esc(d.account_type)} · ••••${esc(d.account_number.slice(-4))}</option>`).join('');if(state.destinations.some(d=>d.id===current))$('#bank-destination').value=current;else if(state.destinations.length===1)$('#bank-destination').value=state.destinations[0].id;$('#destinations-list').innerHTML=state.destinations.map(d=>`<div class="player-row"><span class="action-icon">▤</span><div><div class="name">${esc(d.bank)}</div><div class="role">${esc(d.account_type)} · ••••${esc(d.account_number.slice(-4))}</div></div></div>`).join('');updateBankButton()}
function bankReviewPending(){modal('Revisión de Financed pendiente',`<p>Los retiros de esta cuenta están bloqueados.</p><button class="primary full" id="pending-review-close">Entendido</button>`);$('#pending-review-close').onclick=close}
function updateBankButton(){const d=state.destinations.find(d=>d.id===$('#bank-destination').value);const pending=!!me()?.bank_review_requested_at,button=$('#bank-send-button');button.textContent=pending?'Ver estado de revisión':d?'Enviar dinero a '+d.bank:'Enviar dinero al banco';button.type=pending?'button':'submit';button.onclick=pending?bankReviewPending:null;$('#bank-review-status').hidden=!pending}
$('#bank-destination').onchange=updateBankButton;
function validAmount(n){if(!Number.isSafeInteger(n)||n<=0||n>100000000)throw Error('Ingresa un monto entero mayor que cero');if(n>me().balance)throw Error('Saldo insuficiente')}
async function transfer(to,amount,concept,key){validAmount(amount);if(!state.contacts.some(c=>c.id===to))throw Error('Agrega ese usuario a tus contactos');if(connected){await rpc('transfer',{p_to:to,p_amount:amount,p_concept:concept,p_key:key});await sync()}else throw Error('Inicia sesión y agrega un contacto para transferir')}
function receipt(amount,to,concept,key){modal('Transferencia realizada',`<div class="receipt-success">✓</div><div class="receipt-amount">${money(amount)}</div><div class="receipt-row"><span>Para</span><b>${esc(to)}</b></div><div class="receipt-row"><span>Concepto</span><b>${esc(concept)}</b></div><div class="receipt-row"><span>Fecha</span><span>${new Date().toLocaleString('es-CL')}</span></div><p>Comprobante ${esc(key.slice(0,8).toUpperCase())}</p><button class="primary full" id="done">Volver a mi cuenta</button>`);$('#done').onclick=()=>{close();navigate('overview')}}
function review(to,amount,concept){try{validAmount(amount);const c=state.contacts.find(c=>c.id===to);if(!c)throw Error('Selecciona un contacto');const key=crypto.randomUUID();modal('Revisar transferencia',`<div class="receipt-amount">${money(amount)}</div><div class="receipt-row"><span>Desde</span><b>${esc(me().name)}</b></div><div class="receipt-row"><span>Para</span><b>${esc(c.name)} · @${esc(c.username)}</b></div><div class="receipt-row"><span>Concepto</span><b>${esc(concept)}</b></div><p class="error" id="modal-error"></p><div class="modal-actions"><button class="outline" id="cancel-op">Volver</button><button class="primary" id="confirm-operation">Confirmar transferencia</button></div>`);$('#cancel-op').onclick=close;$('#confirm-operation').onclick=()=>run(async()=>{await transfer(to,amount,concept,key);$('#transfer-form').reset();receipt(amount,c.name,concept,key)})}catch(e){toast(e.message)}}
$('#transfer-form').onsubmit=e=>{e.preventDefault();review($('#recipient').value,Number($('#amount').value),$('#concept').value)};$('#history-filter').onchange=render;
function contacts(){navigate('players');$('#search-username').focus()}
$('#invite').onclick=contacts;$('#collect-go').onclick=()=>{modal('Tu nombre de usuario',`<p>Comparte este nombre para que puedan agregarte y transferirte.</p><div class="code-big">@${esc(me().username)}</div><button class="primary full" id="copy-username">Copiar usuario</button>`);$('#copy-username').onclick=async()=>{try{await navigator.clipboard.writeText('@'+me().username);toast('Usuario copiado')}catch{toast('@'+me().username)}}};$('#pay-bank').onclick=()=>navigate('bank');$('#game-setup').onclick=()=>profile();$('#profile').onclick=()=>profile();$('#settings').onclick=()=>profile();
$('#contact-search').onsubmit=e=>{e.preventDefault();run(async()=>{const username=$('#search-username').value.trim().replace(/^@/,'').toLowerCase();if(!/^[a-z0-9_]{3,20}$/.test(username))throw Error('Busca un usuario de 3–20 letras, números o guion bajo');if(!connected){$('#search-result').innerHTML='<p class="empty">Inicia sesión para buscar usuarios registrados. No hay contactos de ejemplo.</p>';return}const users=await rpc('search',{p_username:username});$('#search-result').innerHTML=users.length?users.map(c=>`<div class="player-row search-match"><span class="avatar">${esc(c.name[0])}</span><div><div class="name">${esc(c.name)}</div><div class="role">@${esc(c.username)}</div></div><button class="primary" data-add="${esc(c.id)}" ${state.contacts.some(x=>x.id===c.id)?'disabled':''}>${state.contacts.some(x=>x.id===c.id)?'Agregado':'Agregar'}</button></div>`).join(''):'<p class="empty">No encontramos ese nombre de usuario.</p>';document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>run(async()=>{await rpc('add_contact',{p_contact:b.dataset.add});await sync();b.disabled=true;b.textContent='Agregado';toast('Contacto agregado')}))})};
$('#destination-form').onsubmit=e=>{e.preventDefault();run(async()=>{const bank=$('#destination-bank').value,type=$('#destination-type').value,number=$('#destination-number').value.trim();if(!/^\d{4,20}$/.test(number))throw Error('Ingresa un número de cuenta de práctica válido');if(connected){await rpc('save_bank',{p_bank:bank,p_type:type,p_number:number});await sync()}else{if(!state.destinations.some(d=>d.bank===bank&&d.account_type===type&&d.account_number===number))state.destinations.push({id:crypto.randomUUID(),bank,account_type:type,account_number:number});renderDestinations()}$('#destination-number').value='';toast('Cuenta de destino guardada')})};
$('#bank-transfer-form').onsubmit=e=>{e.preventDefault();if(me()?.bank_review_requested_at){bankReviewPending();return}try{const d=state.destinations.find(d=>d.id===$('#bank-destination').value),amount=Number($('#bank-transfer-amount').value);if(!d)throw Error('Primero guarda y selecciona tu cuenta de destino');validAmount(amount);identityStep(d,amount)}catch(e){toast(e.message)}};
function identityStep(destination,amount){
 let sides={front:false,back:false};
 modal('Verifica tu identidad para continuar',`<p>Debes verificar tu identidad para proceder con la transferencia a ${esc(destination.bank)}.</p><div class="settings-note">Verificación de práctica: usa un carnet ficticio o las imágenes de ejemplo. Las fotos se muestran solo en este dispositivo; no se guardan ni se envían.</div><div class="document-grid"><div><label for="id-front">Foto del carnet · Anverso</label><input id="id-front" type="file" accept="image/jpeg,image/png,image/webp"><div id="front-preview" class="document-slot">Sin imagen</div></div><div><label for="id-back">Foto del carnet · Reverso</label><input id="id-back" type="file" accept="image/jpeg,image/png,image/webp"><div id="back-preview" class="document-slot">Sin imagen</div></div></div><button id="sample-document" class="text-button" type="button">Usar imágenes de ejemplo</button><div class="receipt-row"><span>Destino</span><b>${esc(destination.bank)} · ••••${esc(destination.account_number.slice(-4))}</b></div><div class="receipt-row"><span>Monto</span><b>${money(amount)}</b></div><p id="modal-error" class="error"></p><div class="modal-actions"><button id="cancel-verification" class="outline">Cancelar</button><button id="complete-verification" class="primary" disabled>Solicitar revisión</button></div>`);
 const ready=()=>{if($('#complete-verification'))$('#complete-verification').disabled=!(sides.front&&sides.back)};
 for(const side of ['front','back'])$('#id-'+side).onchange=e=>{const file=e.target.files[0];sides[side]=false;$('#'+side+'-preview').textContent='Sin imagen';$('#modal-error').textContent='';if(!file){ready();return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){e.target.value='';$('#modal-error').textContent='Elige una imagen JPG, PNG o WebP de hasta 5 MB.';ready();return}const url=URL.createObjectURL(file);documentUrls.push(url);const img=document.createElement('img');img.className='document-preview';img.alt=side==='front'?'Anverso del documento de práctica':'Reverso del documento de práctica';img.onload=()=>{sides[side]=true;ready()};img.onerror=()=>{sides[side]=false;$('#modal-error').textContent='No se pudo leer esa imagen.';ready()};img.src=url;$('#'+side+'-preview').replaceChildren(img);ready()};
 $('#sample-document').onclick=()=>{clearDocuments();for(const side of ['front','back']){$('#id-'+side).value='';$('#'+side+'-preview').textContent='Documento de ejemplo · '+(side==='front'?'Anverso':'Reverso');sides[side]=true}$('#modal-error').textContent='';ready()};$('#cancel-verification').onclick=close;
 $('#complete-verification').onclick=()=>run(async()=>{if(!sides.front||!sides.back)throw Error('Necesitas ambos lados del documento de práctica');validAmount(amount);if(connected){await rpc('request_bank_review',{p_destination:destination.id,p_amount:amount});await sync()}else{state.account.bank_review_requested_at=new Date().toISOString();render()}clearDocuments();$('#bank-transfer-amount').value='';bankReviewPending()});
}
render();setInterval(()=>{if(connected&&session&&!busy&&!document.hidden)sync().catch(()=>{$('#connection-banner').innerHTML='<span>Sin sincronizar</span> No se pudo actualizar la cuenta. Reintentando…'})},3000);
if(document.modelContext?.registerTool)try{document.modelContext.registerTool({name:'read_financed_account',description:'Consultar la cuenta, contactos agregados y movimientos visibles. No devuelve documentos.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async()=>{if($('#bank-app').hidden)throw Error('Abre tu cuenta primero');if(connected)await sync();return structuredClone(state)}});document.modelContext.registerTool({name:'review_financed_transfer',description:'Preparar una transferencia a un contacto agregado. El usuario confirma en la interfaz.',inputSchema:{type:'object',properties:{recipient_id:{type:'string'},amount:{type:'integer',minimum:1},concept:{type:'string'}},required:['recipient_id','amount','concept'],additionalProperties:false},execute:async x=>{if($('#bank-app').hidden)throw Error('Abre tu cuenta primero');validAmount(x.amount);if(!state.contacts.some(c=>c.id===x.recipient_id)||typeof x.concept!=='string'||x.concept.length>80)throw Error('Contacto o concepto inválido');review(x.recipient_id,x.amount,x.concept);return {status:'awaiting_user_confirmation'}}})}catch(e){console.warn('WebMCP no disponible')}
